mapper.select:
SELECT id, order_no, category_id, category_name, quantity, material_id, material_batch_code, mold_no, machine_no, status, plan_start_time, actual_start_time, actual_end_time, production_hours, qualified_quantity, scrap_quantity, operator, technician, remark, create_time, update_time FROM production_order WHERE deleted = 0
AND order_no LIKE CONCAT('%', #{query.orderNo}, '%')
AND category_id = #{query.categoryId}
AND status = #{query.status}
AND operator LIKE CONCAT('%', #{query.operator}, '%')
AND create_time >= #{query.startTime}
AND create_time <= #{query.endTime}
ORDER BY create_time DESC
